/**
 * Pins the probe-deadline poll machinery: the cancellation flag's latch/deadline/extra-supplier semantics, the
 * stackless singleton thrown by {@link KernelRuntime#checkCancelled}, and — the integration risk of the emitter change
 * — that a kernel written in exactly the emitted poll pattern compiles in Janino's child classloader (public SPI
 * visibility of {@link KernelCancellation}), runs to completion untouched when no cancellation is bound, and aborts
 * within one mask window (1024 iterations) of a tripped deadline.
 */
class LmdbNativeKernelPollPointTest {
	private static final long FUTURE_TIMEOUT_SECONDS = 5L;

	@Test
	void cancellationLatchesOnDeadlineManualCancelAndExtraSupplier() {
		KernelCancellation expired = new KernelCancellation(System.nanoTime() - 1L);
		assertTrue(expired.cancelled(), "a past deadline cancels on the first poll");
		assertTrue(expired.cancelled(), "and latches");

		KernelCancellation future = new KernelCancellation(System.nanoTime() + 3_600_000_000_000L);
		assertFalse(future.cancelled(), "an hour-away deadline does not cancel");
		future.cancel();
		assertTrue(future.cancelled(), "manual cancel latches");

		AtomicBoolean group = new AtomicBoolean();
		KernelCancellation withExtra = new KernelCancellation(System.nanoTime() + 3_600_000_000_000L, group::get);
		assertFalse(withExtra.cancelled());
		group.set(true);
		assertTrue(withExtra.cancelled(), "a parallel group's cancelled flag folds in");
	}

	@Test
	void checkCancelledThrowsTheStacklessSingletonAndIgnoresNull() {
		KernelRuntime.checkCancelled(null);
		KernelCancellation live = new KernelCancellation(System.nanoTime() + 3_600_000_000_000L);
		KernelRuntime.checkCancelled(live);
		KernelCancellation tripped = new KernelCancellation(System.nanoTime() - 1L);
		KernelCancelledException thrown = assertThrows(KernelCancelledException.class,
				() -> KernelRuntime.checkCancelled(tripped));
		assertSame(KernelCancelledException.INSTANCE, thrown, "the exception is the shared stackless instance");
		assertEquals(0, thrown.getStackTrace().length, "stackless by construction");
	}

	@Test
	void queryCancellationIsTerminalAndWinsARaceWithProbeExpiry() {
		AtomicBoolean queryCancelled = new AtomicBoolean();
		KernelCancellation queryOnly = new KernelCancellation(System.nanoTime() + TimeUnit.HOURS.toNanos(1L), null,
				queryCancelled::get);
		queryCancelled.set(true);
		KernelQueryCancelledException querySignal = assertThrows(KernelQueryCancelledException.class,
				() -> KernelRuntime.checkCancelled(queryOnly));
		assertSame(KernelQueryCancelledException.INSTANCE, querySignal);

		KernelCancellation simultaneous = new KernelCancellation(System.nanoTime() - 1L, null, () -> true);
		assertSame(KernelQueryCancelledException.INSTANCE,
				assertThrows(KernelQueryCancelledException.class, () -> KernelRuntime.checkCancelled(simultaneous)),
				"evaluation cancellation must not become a replayable probe decline when both signals race");
	}

	@Test
	void materializingSinkObservesQueryCancellationWithoutAProbeLimit() {
		KernelCancellation cancellation = new KernelCancellation(
				System.nanoTime() + TimeUnit.HOURS.toNanos(1L), null, () -> true);

		assertSame(KernelQueryCancelledException.INSTANCE,
				assertThrows(KernelQueryCancelledException.class,
						() -> KernelRuntime.checkMaterializationCapacity(cancellation, 0)),
				"a blocking kernel must observe evaluation cancellation before growing its private result array");
	}

	@Test
	void interruptedEvaluationThreadBecomesTerminalQueryCancellation() {
		NativeCancellationToken evaluation = new NativeCancellationToken();
		KernelCancellation cancellation = LmdbNativeProbeDeadline
				.currentKernelCancellation(evaluation::isCancellationRequested);
		Thread.currentThread().interrupt();
		try {
			assertSame(KernelQueryCancelledException.INSTANCE,
					assertThrows(KernelQueryCancelledException.class,
							() -> KernelRuntime.checkCancelled(cancellation)),
					"SailSourceConnection explain interrupts its evaluation thread on timeout; native poll points must "
							+ "classify that signal as terminal query cancellation");
		} finally {
			Thread.interrupted();
		}
	}

	@Test
	void parallelWorkerGroupCancellationUsesProbeControlFlow() {
		AtomicBoolean workerGroupCancelled = new AtomicBoolean();
		AtomicBoolean queryCancelled = new AtomicBoolean();
		try (LmdbNativeProbeDeadline.Scope ignored = LmdbNativeProbeDeadline
				.enter(LmdbNativeProbeDeadline.trippableOnly())) {
			KernelCancellation cancellation = LmdbNativeProbeDeadline
					.currentKernelCancellation(queryCancelled::get, workerGroupCancelled::get);
			workerGroupCancelled.set(true);
			assertSame(KernelCancelledException.INSTANCE,
					assertThrows(KernelCancelledException.class, () -> KernelRuntime.checkCancelled(cancellation)),
					"an abandoned parallel proposal is replayable probe control flow, not query cancellation");
		}

		try (LmdbNativeProbeDeadline.Scope ignored = LmdbNativeProbeDeadline
				.enter(LmdbNativeProbeDeadline.trippableOnly())) {
			KernelCancellation simultaneous = LmdbNativeProbeDeadline
					.currentKernelCancellation(queryCancelled::get, workerGroupCancelled::get);
			queryCancelled.set(true);
			assertSame(KernelQueryCancelledException.INSTANCE,
					assertThrows(KernelQueryCancelledException.class, () -> KernelRuntime.checkCancelled(simultaneous)),
					"terminal evaluation cancellation still wins when both signals are set");
		}
	}

	@Test
	void aGeneratedStyleKernelPollsWithinOneMaskWindow() throws Exception {
		// Exactly the emitter's poll pattern: cancel/pollTick fields, bind from context, masked check in the loop.
		String source = "package org.eclipse.rdf4j.sail.lmdb.gen;\n"
				+ "import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.JaninoKernel;\n"
				+ "import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelCancellation;\n"
				+ "import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelContext;\n"
				+ "import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelRuntime;\n"
				+ "public final class PollProbeKernel implements JaninoKernel {\n"
				+ "    private KernelCancellation cancel;\n"
				+ "    private int pollTick;\n"
				+ "    public long iterations;\n"
				+ "    public void bind(KernelContext context) {\n"
				+ "        cancel = context.cancellation;\n"
				+ "    }\n"
				+ "    public int fill(long[] out, int max) {\n"
				+ "        for (long i = 0L; i < 10_000_000L; i++) {\n"
				+ "            if ((++pollTick & 1023) == 0) { KernelRuntime.checkCancelled(cancel); }\n"
				+ "            iterations = i;\n"
				+ "        }\n"
				+ "        return 0;\n"
				+ "    }\n"
				+ "    public void close() {\n"
				+ "    }\n"
				+ "}\n";
		SimpleCompiler compiler = new SimpleCompiler();
		compiler.setParentClassLoader(JaninoKernel.class.getClassLoader());
		compiler.cook(source);
		Class<?> kernelClass = compiler.getClassLoader().loadClass("org.eclipse.rdf4j.sail.lmdb.gen.PollProbeKernel");

		KernelContext plain = new KernelContext(null, new long[0], new long[0], null);
		JaninoKernel untouched = (JaninoKernel) kernelClass.getDeclaredConstructor().newInstance();
		untouched.bind(plain);
		assertEquals(0, untouched.fill(new long[0], 0), "a null cancellation never aborts");

		KernelContext probed = new KernelContext(null, new long[0], new long[0], null)
				.withCancellation(new KernelCancellation(System.nanoTime() - 1L));
		JaninoKernel probedKernel = (JaninoKernel) kernelClass.getDeclaredConstructor().newInstance();
		probedKernel.bind(probed);
		assertThrows(KernelCancelledException.class, () -> probedKernel.fill(new long[0], 0));
		long iterations = (Long) kernelClass.getField("iterations").get(probedKernel);
		assertTrue(iterations < 1024, "the tripped deadline must abort within one mask window, ran " + iterations);
	}

	@Test
	void inFlightCancellationStopsGeneratedStylePollLoopAtNextMaskWindow() throws Exception {
		KernelCancellation cancellation = new KernelCancellation(System.nanoTime() + TimeUnit.HOURS.toNanos(1L));
		CountDownLatch entered = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		AtomicLong iterations = new AtomicLong(-1L);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<?> worker = executor.submit(() -> {
			entered.countDown();
			await(release);
			int pollTick = 0;
			for (long i = 0L; i < 10_000_000L; i++) {
				if ((++pollTick & 1023) == 0) {
					KernelRuntime.checkCancelled(cancellation);
				}
				iterations.set(i);
			}
		});

		try {
			assertTrue(entered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"the kernel-style worker must be in flight before cancellation");
			cancellation.cancel();
			release.countDown();

			ExecutionException aborted = assertThrows(ExecutionException.class,
					() -> worker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));
			assertSame(KernelCancelledException.INSTANCE, aborted.getCause(),
					"the first masked poll must surface the shared cooperative-cancellation signal");
			assertTrue(iterations.get() < 1024,
					"in-flight cancellation must abort within one mask window, ran " + iterations.get());
		} finally {
			release.countDown();
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
				throw new AssertionError("timed out waiting for kernel poll-loop release");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("kernel worker interrupted while awaiting release", e);
		}
	}
}
